    "context": "João Batista, na prisão, manda perguntar se Jesus é mesmo aquele que havia de vir — o profeta que o anunciou agora duvida. Jesus responde sem repreendê-lo e depois o elogia publicamente. Segue-se uma crítica à geração que não se satisfaz com nada, um lamento sobre as cidades que viram milagres e não mudaram, e então, sem transição, o convite mais terno do evangelho.",
