    "context": "Mesmo discurso do Monte das Oliveiras que Marcos registra, mas Mateus o expande com parábolas no capítulo seguinte. Os discípulos apontam os edifícios do templo e Jesus anuncia sua destruição. Seguem-se sinais, advertências contra falsos messias, a imagem do relâmpago que se vê de ponta a ponta e a comparação com os dias de Noé, quando as pessoas simplesmente comiam, bebiam e se casavam — sem perceber.",
