      "A palavra que Marcos escolhe é clínica: pṓrōsis, a casca que se forma sobre a fratura. Corações endurecidos raramente começaram duros. Endureceram para não doer de novo. Isso não desculpa, mas explica — e muda a maneira de orar por quem está assim.",
      "V.35 fecha o capítulo redesenhando família: quem faz a vontade de Deus é irmão, irmã e mãe. Jesus diz isso enquanto a família biológica espera do lado de fora, convencida de que ele perdeu o juízo. Ele não nega os seus; amplia o círculo."
