      "A bênção não está em ajudar, está em não poder ser retribuído. Isso desmonta a generosidade que investe esperando retorno, inclusive retorno em gratidão ou reputação.",
      "As três desculpas da parábola são todas legítimas: negócios, trabalho, casamento. Ninguém recusa por maldade. É a vida comum, bem organizada, que enche a agenda e esvazia a mesa."
