    "context": "Jesus está no templo e observa as pessoas colocando ofertas no gazofilácio. Vê uma viúva pobre colocar duas pequenas moedas e faz o comentário. Logo em seguida, alguns admiram as pedras e os ornamentos do templo, e ele anuncia que não ficará pedra sobre pedra. O discurso sobre o fim ocupa o resto do capítulo, e termina com o conselho de vigiar e orar, e a nota de que ele passava as noites no Monte das Oliveiras.",
